const c=await reserve(q,at(200)); console.log("3",c.allowed);
console.log("cap",await reserve(q,at(400)));
console.log("release",await release(c.reservationId), await release(c.reservationId));
console.log("after release",(await reserve(q,at(400))).allowed);
console.log("expiry",(await reserve(q,at(24*60+1))).allowed);
